"""
    Gets the query string of a URL parameter dictionary.abs
    :param params: URL params.
    :return: Query string.
    """
def get_query_string(params: Any) -> str {
    if not params {
        return '';
    }
    return ('?' + '&'.join([(str(k) + '=' + str(v)) for (k, v) in params.items()]));
}

